explorer_js='''(()=>{const $=s=>document.querySelector(s),grid=$('#businessGrid'),count=$('#businessCount'),manifest=$('#businessManifest');const c={style:$('#businessStyle'),palette:$('#businessPalette'),treatment:$('#businessTreatment'),motion:$('#businessMotion'),state:$('#businessState'),size:$('#businessSize'),energy:$('#businessEnergy'),search:$('#businessSearch')};let filter='all';function matches(def){const term=c.search.value.trim().toLowerCase(),hay=[def.name,def.slug,def.group,...def.keywords,...def.intents].join(' ').toLowerCase();if(term&&!hay.includes(term))return false;if(filter==='bespoke'&&!def.bespokeInternalMotion)return false;if(!['all','bespoke'].includes(filter)&&def.group!==filter)return false;return true}function state(def){return def.states.includes(c.state.value)?c.state.value:(c.state.value==='completed'?'active':def.states[0])}function card(def){const a=document.createElement('article');a.className='icon-card'+(['expense','decline'].includes(def.slug)?' business-negative':'');a.dataset.iconId=def.id;a.innerHTML=`<header class="icon-card-head"><div><h3>${def.name}</h3><div class="icon-card-id">${def.id}</div></div><div class="icon-card-badges"><span class="icon-card-badge">${def.bespokeInternalMotion?'semantic':'shared'}</span><span class="icon-card-badge">${def.group}</span></div></header><div class="icon-stage"></div><div class="business-group">${def.intents.join(' · ')}</div><footer class="icon-card-actions"><button data-action="replay">Replay</button><button data-action="manifest">Manifest</button></footer>`;const icon=NexBusinessIcons.create(def,{size:Number(c.size.value),treatment:c.treatment.value,state:state(def)});a.querySelector('.icon-stage').appendChild(icon);icon.__tl=NexBusinessIcons.animate(icon,{motion:c.motion.value,energy:c.energy.value});icon.__tl.seek(icon.__tl.duration());a.querySelector('[data-action=replay]').onclick=()=>icon.__tl.restart();a.querySelector('[data-action=manifest]').onclick=()=>{manifest.querySelector('pre').textContent=JSON.stringify(def,null,2);manifest.classList.add('open')};return a}function render(){NexTheme.setStyle(c.style.value);NexTheme.applyPalette(c.palette.value);NexTheme.setEnergy(c.energy.value);const defs=NexBusinessIcons.registry.filter(matches);grid.replaceChildren(...defs.map(card));count.textContent=defs.length}Object.values(c).forEach(el=>el.addEventListener(el===c.search?'input':'change',render));document.querySelectorAll('.icon-filter').forEach(btn=>btn.onclick=()=>{filter=btn.dataset.filter;document.querySelectorAll('.icon-filter').forEach(x=>x.classList.toggle('active',x===btn));render()});[['businessPrimary','primary'],['businessSecondary','secondary'],['businessAccent','accent']].forEach(([id,key])=>$('#'+id).oninput=e=>document.documentElement.style.setProperty('--'+key,e.target.value));$('#businessReplayAll').onclick=()=>[...grid.querySelectorAll('.nex-icon')].forEach((el,i)=>setTimeout(()=>el.__tl?.restart(),i*22));$('#closeBusinessManifest').onclick=()=>manifest.classList.remove('open');window.NexBusinessExplorer={render,get filter(){return filter}};render()})();'''
(root/'runtime/business-icon-explorer.js').write_text(explorer_js)

# Scene styling and three demos
(root/'styles/business-scenes.css').write_text('''html,body{width:100%;height:100%;overflow:hidden}.business-scene{position:relative;width:100%;height:100%;overflow:hidden;background:var(--paper-bg);color:var(--ink);isolation:isolate}.business-scene:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 82% 16%,color-mix(in srgb,var(--secondary) 38%,transparent),transparent 30%),repeating-linear-gradient(0deg,transparent 0 40px,color-mix(in srgb,var(--ink) 5%,transparent) 41px 42px)}.business-layout{position:relative;z-index:2;width:100%;height:100%;display:grid;grid-template-columns:.9fr 1.1fr;gap:60px;padding:80px 92px}.business-copy{display:flex;flex-direction:column;justify-content:space-between}.business-kicker{font:900 14px var(--mono-font);letter-spacing:.13em}.business-scene h1{font:900 clamp(76px,6.5vw,128px)/.84 var(--display-font);letter-spacing:-.075em;margin:18px 0}.business-scene p{font:700 21px/1.42 var(--mono-font);color:var(--ink-muted);max-width:680px}.business-tags{display:flex;gap:10px;flex-wrap:wrap}.business-tags span{border:2px solid var(--ink);background:var(--paper-surface);box-shadow:4px 4px 0 var(--ink);padding:8px 11px;font:900 11px var(--mono-font)}.business-board{display:grid;grid-template-columns:repeat(4,1fr);grid-template-rows:repeat(2,1fr);gap:18px;padding:28px;border:3px solid var(--ink);background:var(--paper-surface);box-shadow:15px 17px 0 var(--ink)}.business-node{display:grid;place-items:center;border:2px dashed color-mix(in srgb,var(--ink) 60%,transparent);background:color-mix(in srgb,var(--paper-surface) 82%,var(--highlight));min-width:0}.business-node-label{font:900 9px var(--mono-font);text-transform:uppercase;margin-top:7px}.business-scene[data-ratio="square"] .business-layout{grid-template-columns:1fr;grid-template-rows:auto 1fr;padding:52px;gap:28px}.business-scene[data-ratio="square"] .business-copy{display:grid;grid-template-columns:1fr .75fr;gap:28px;align-items:end}.business-scene[data-ratio="square"] h1{font-size:80px}.business-scene[data-ratio="square"] p{font-size:16px}.business-scene[data-ratio="square"] .business-board{min-height:540px}.business-scene[data-ratio="portrait"] .business-layout{grid-template-columns:1fr;grid-template-rows:auto 1fr;padding:70px 58px;gap:40px}.business-scene[data-ratio="portrait"] h1{font-size:108px}.business-scene[data-ratio="portrait"] p{font-size:21px}.business-scene[data-ratio="portrait"] .business-board{grid-template-columns:repeat(2,1fr);grid-template-rows:repeat(4,1fr);min-height:930px}''')
scene_defs=[
('commerce-workflow','16:9',1920,1080,'clean-editorial','warm','FROM CART TO DOOR','A complete commerce journey moves through product, cart, order, payment, package, delivery, receipt and customer support.',['product','shopping-cart','order','payment','package','delivery','receipt','support']),
('campaign-result','1:1',1080,1080,'bold-paper-collage','cobalt','CAMPAIGN TO CONVERSION','Campaign reach becomes audience, leads, funnel movement, conversion, sales, revenue and measurable performance.',['campaign','audience','leads','funnel','conversion','sales','revenue','performance']),
('milestone-scene','9:16',1080,1920,'handmade-scrapbook','charcoal','FROM GOAL TO MILESTONE','Targets create goals; partnerships and teams drive launch, growth, milestones, trophies and the next market opportunity.',['target','goal','partnership','team','launch','growth','milestone','trophy'])]
for id_,ratio,w,h,style,palette,title,body,slugs in scene_defs:
    nodes=''.join(f'<div class="business-node" data-icon="{s}"><div class="business-mount"></div><div class="business-node-label">{s.replace("-"," ")}</div></div>' for s in slugs)
    r='landscape' if ratio=='16:9' else 'square' if ratio=='1:1' else 'portrait'
    html=f'''<!doctype html><html lang="en" data-paper-style="{style}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="../styles/tokens.css"><link rel="stylesheet" href="../styles/paper.css"><link rel="stylesheet" href="../styles/motion.css"><link rel="stylesheet" href="../styles/icons.css"><link rel="stylesheet" href="../styles/business-icons.css"><link rel="stylesheet" href="../styles/business-scenes.css"></head><body><main id="{id_}" class="business-scene" data-composition-id="{id_}" data-start="0" data-duration="10.8" data-track-index="1" data-width="{w}" data-height="{h}" data-ratio="{r}"><div class="business-layout"><section class="business-copy"><div><div class="business-kicker">NEXSTUDIO / BATCH 7</div><h1>{title}</h1><p>{body}</p></div><div class="business-tags"><span>36 BUSINESS ICONS</span><span>24 SEMANTIC MOTIONS</span><span>AGENT-READY</span></div></section><section class="business-board">{nodes}</section></div></main><script src="../vendor/gsap-compat.js"></script><script src="../runtime/theme.js"></script><script>NexTheme.applyPalette('{palette}');NexTheme.setStyle('{style}')</script><script src="../runtime/motion-registry.js"></script><script src="../runtime/motion-engine.js"></script><script src="../runtime/business-icon-registry.js"></script><script src="../components/business-icons.js"></script><script src="../runtime/business-scene-demo.js"></script></body></html>'''
    (root/'compositions'/f'{id_}.html').write_text(html)
scene_js='''(()=>{const root=document.querySelector('.business-scene'),nodes=[...root.querySelectorAll('.business-node')],ratio=root.dataset.ratio;const sizes=ratio==='portrait'?[150,126,126,126,126,126,126,142]:ratio==='square'?[142,108,108,108,108,108,108,124]:[174,108,108,108,108,108,108,136];const entries=[];nodes.forEach((node,i)=>{const def=NexBusinessIcons.getDef(node.dataset.icon),icon=NexBusinessIcons.create(def,{size:sizes[i]||108,state:i===nodes.length-1&&def.states.includes('completed')?'completed':'active'});node.querySelector('.business-mount').appendChild(icon);const tl=NexBusinessIcons.animate(icon,{duration:1.14+(i%3)*.14,energy:i===0?'high':'medium'});entries.push({timeline:tl,offset:.5+i*.68})});const copy=gsap.timeline({paused:true});copy.fromTo(root.querySelector('.business-kicker'),{opacity:0,x:-35},{opacity:1,x:0,duration:.5,ease:'power3.out'},.12);copy.fromTo(root.querySelector('h1'),{opacity:0,y:65},{opacity:1,y:0,duration:.75,ease:'expo.out'},.2);copy.fromTo(root.querySelector('p'),{opacity:0,y:28},{opacity:1,y:0,duration:.55,ease:'power2.out'},.5);copy.fromTo(root.querySelector('.business-board'),{opacity:0,x:60,rotation:2},{opacity:1,x:0,rotation:0,duration:.78,ease:'back.out(1.7)'},.28);copy.fromTo(root.querySelector('.business-tags'),{opacity:0,y:18},{opacity:1,y:0,duration:.45,ease:'power2.out'},.8);entries.push({timeline:copy,offset:0});const ambient=gsap.timeline({paused:true});nodes.forEach((n,i)=>{const y=i%2?5:-5,r=i%2?.4:-.4;ambient.fromTo(n,{y:0,rotation:0},{y,rotation:r,duration:1,ease:'sine.inOut'},6.15+i*.04);ambient.to(n,{y:-y,rotation:-r,duration:1,ease:'sine.inOut'},7.15+i*.04);ambient.to(n,{y,rotation:r,duration:1,ease:'sine.inOut'},8.15+i*.04);ambient.to(n,{y:0,rotation:0,duration:1,ease:'sine.inOut'},9.15+i*.04)});entries.push({timeline:ambient,offset:0});const controller=new NexBusinessIcons.CombinedTimeline(entries);controller._duration=10.8;controller.seek(0);window.__timelines=window.__timelines||{};window.__timelines[root.id]=controller;window.seekComposition=t=>controller.seek(t);const p=new URLSearchParams(location.search);if(p.has('t'))controller.seek(Number(p.get('t')));else if(p.get('autoplay')==='1')controller.restart();})();'''
(root/'runtime/business-scene-demo.js').write_text(scene_js)

